SELECT s1."c0" AS "id", s1."c1" AS "customer", s1."c2" AS "amount" FROM (SELECT s2."c3" AS "c0", s2."c4" AS "c1", s2."c5" AS "c2" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c2" AS "c2", s3."c0" AS "c3", s3."c1" AS "c4", s3."c2" AS "c5" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1", s4."c2" AS "c2" FROM (SELECT "id" AS "c0", "customer" AS "c1", "amount" AS "c2" FROM "orders") AS s4 WHERE NOT EXISTS (SELECT 1 FROM (SELECT "name" AS "c0", "city" AS "c1" FROM "customers") AS s5 WHERE COALESCE((s4."c1" = s5."c0"), FALSE))) AS s3) AS s2) AS s1
